<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Services\MembershipLifecycleService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema;
class MembershipCycleHealthController extends Controller {
    public function show(Request $r,int $id): JsonResponse { $m=DB::table('nurselink_memberships')->where('id',$id)->first(); abort_unless($m,404); $approved=strtolower((string)$m->status)==='approved'; $checks=['smart_profile'=>Schema::hasTable('nurselink_smart_registration_profiles')&&DB::table('nurselink_smart_registration_profiles')->where('user_id',$m->user_id)->exists(),'evidence'=>Schema::hasTable('nurselink_smart_registration_documents')&&DB::table('nurselink_smart_registration_documents')->where('user_id',$m->user_id)->where('active',true)->exists(),'history'=>!Schema::hasTable('nurselink_membership_status_history')||DB::table('nurselink_membership_status_history')->where('membership_id',$id)->exists(),'member_number'=>!$approved||trim((string)($m->member_number??''))!=='','onboarding'=>!$approved||(!Schema::hasTable('nurselink_membership_onboarding')||DB::table('nurselink_membership_onboarding')->where('user_id',$m->user_id)->exists())]; $repairable=$approved&&$checks['member_number']&&!$checks['onboarding']; $ok=!in_array(false,$checks,true); return response()->json(['data'=>['status'=>$ok?'healthy':($repairable?'action_required':'check_needed'),'checks'=>$checks,'repairable'=>$repairable]]); }
    public function reconcile(Request $r,int $id,MembershipLifecycleService $life): JsonResponse { $d=$r->validate(['reason'=>'required|string|min:8|max:1000']); $m=DB::table('nurselink_memberships')->where('id',$id)->first(); abort_unless($m,404); abort_unless(strtolower((string)$m->status)==='approved',409); abort_if(trim((string)($m->member_number??''))==='',409,'Missing member number requires manual review.'); DB::transaction(function()use($m,$life,$d){ if(Schema::hasColumn('users','member_number'))DB::table('users')->where('id',$m->user_id)->update(['member_number'=>$m->member_number,'updated_at'=>now()]); $life->ensureOnboarding($m); $life->recordTransition($m,'approved','approved',null,'Derived-state reconciliation: '.$d['reason'],['reconcile'=>true]); }); return $this->show($r,$id); }
}
